import time
import smbus

# I2C address of the ADS1115 ADC
ADS1115_ADDRESS = 0x48

# Register addresses for the four channels
ADS1115_REG_CONVERSION = 0x00
ADS1115_REG_CONFIG = 0x01

# Configuration settings (single-shot, single-ended, ±4.096V range, 128 SPS)
CONFIG_START = 0xC383
CONFIG_MULTI_RANGE = 0x0000
CONFIG_MULTI_MODE = 0x0100
CONFIG_MULTI_DR_128 = 0x0100
CONFIG_MULTI_PGA_4_096V = 0x0000
CONFIG_MUX_AIN0_GND = 0x4000
CONFIG_MUX_AIN1_GND = 0x4800
CONFIG_MUX_AIN2_GND = 0x5000
CONFIG_MUX_AIN3_GND = 0x5800


def swap_endian(word):
    """Swap the endianness of a 16-bit word."""
    return ((word & 0xff00) >> 8) | ((word & 0x00ff) << 8)


def read_adc_raw(channel):
    """Read the raw ADC value from the specified channel."""
    config = CONFIG_START | CONFIG_MULTI_DR_128 | CONFIG_MULTI_PGA_4_096V | CONFIG_MUX_AIN0_GND

    if channel == 0:
        config |= CONFIG_MUX_AIN0_GND
    elif channel == 1:
        config |= CONFIG_MUX_AIN1_GND
    elif channel == 2:
        config |= CONFIG_MUX_AIN2_GND
    elif channel == 3:
        config |= CONFIG_MUX_AIN3_GND
    else:
        raise ValueError("Invalid channel number")

    try:
        bus.write_word_data(ADS1115_ADDRESS, ADS1115_REG_CONFIG, swap_endian(config))
        start_time = time.time()
        while True:
            status = swap_endian(bus.read_word_data(ADS1115_ADDRESS, ADS1115_REG_CONFIG))
            if (status & 0x8000) == 0:
                break
            if time.time() - start_time > 0.1:
                raise TimeoutError("Timeout waiting for conversion")
            time.sleep(0.001)
        return swap_endian(bus.read_word_data(ADS1115_ADDRESS, ADS1115_REG_CONVERSION))
    except (IOError, TimeoutError) as e:
        print(f"Error reading channel {channel}: {e}")
        return None


if __name__ == "__main__":
    bus = smbus.SMBus(1)  # Initialize I2C bus

    try:
        while True:
            channel0_value = read_adc_raw(0)
            channel1_value = read_adc_raw(1)
            channel2_value = read_adc_raw(2)
            channel3_value = read_adc_raw(3)

            if channel0_value is not None:
                print(f"Channel 0: {channel0_value:05d}", end="")
            else:
                print("Channel 0: Error", end="")

            if channel1_value is not None:
                print(f"{channel1_value:05d}", end="")
            else:
                print(f"Channel 1: Error {channel1_value}", end="")

            if channel2_value is not None:
                print(f"{channel2_value:05d}", end="")
            else:
                print(f"Channel 2: Error {channel2_value}", end="")

            if channel3_value is not None:
                print(f"{channel3_value:05d}\n", end="")
            else:
                print(f"Channel 3: Error {channel3_value}\n", end="")

            time.sleep(0.05)
    except KeyboardInterrupt:
        print("\nExiting")
    finally:
        bus.close()

