import time
import board
import busio
import adafruit_ads1x15.ads1115 as ADS
from typing import List, Tuple

# Constants for ADS1115 configuration
I2C_BUS = 1
GAIN = 1

def initialize_i2c_bus(bus_number: int) -> busio.I2C:
    """Initialize and return an I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA, busnum=bus_number)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        raise

def initialize_adc(i2c_bus: busio.I2C) -> ADS.ADS1115:
    """Initialize and return an ADS1115 ADC."""
    try:
        return ADS.ADS1115(i2c_bus)
    except Exception as e:
        print(f"Error initializing ADS1115: {e}")
        raise

def read_adc_channels(adc: ADS.ADS1115) -> List[int]:
    """Read all four ADC channels and return the raw values."""
    try:
        return [adc.read_adc(i) for i in range(4)]
    except Exception as e:
        print(f"Error reading ADC channels: {e}")
        return [0] * 4  # Return default values in case of error

def format_output(values: List[int]) -> str:
    """Format the ADC values into a table row string."""
    return '| {0:>6} | {1:>6} | {2:>6} | {3:>6} |'.format(*values)

def print_header() -> None:
    """Print the header for the ADC table."""
    print('| {0:>6} | {1:>6} | {2:>6} | {3:>6} |'.format(*range(4)))
    print('-' * 37)

def main() -> None:
    """Main function to read and display ADC values."""
    try:
        i2c_bus = initialize_i2c_bus(I2C_BUS)
        adc = initialize_adc(i2c_bus)

        while True:
            values = read_adc_channels(adc)
            print(format_output(values))
            time.sleep(0.5)

    except KeyboardInterrupt:
        print("Exiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        print("Program finished.")

if __name__ == "__main__":
    main()

