        global config, model_loaded
        try:
            model_file = data["file"]
            if not os.path.exists(model_file):
                raise FileNotFoundError(f"Model file not found: {model_file}")

            if config.model_file != model_file:
                config.model_file = model_file
                logging.info(f"Model file changed to: {config.model_file}")

                if classifier:
                    classifier.close()
                classifier = Predictor(config.model_file, config.labels)
                model_loaded = True
        except FileNotFoundError as e:
            logging.error(f"Error loading model: {e}")
        except Exception as e:
            logging.error(f"Error changing model file: {e}")

    @socketio.on("reload_configuration")
    def reload_configuration():
        """Reloads the configuration when the /reload_configuration endpoint is hit."""
        global config
        try:
            with open(config.RELOAD_FILE, "r") as f:
                reload_config = json.load(f)
            logging.info("Reloading configuration...")
            config.update_from_dict(reload_config)
            logging.info(f"Configuration reloaded. New settings: {config.to_dict()}")
        except FileNotFoundError:
            logging.warning("Reload file not found.")
        except json.JSONDecodeError:
            logging.error("Error decoding JSON from reload file.")
        except Exception as e:
            logging.error(f"Error reloading configuration: {e}")

    socketio.start_background_task(func=check_for_objects)
    return app.run(host=config.HOST, port=config.PORT, debug=config.DEBUG, use_reloader=False)


def generate_frames():
    """Generates frames for the video stream."""
    while True:
        try:
            if not config.send_email_alerts and config.camera_enabled:
                logging.warning("Camera enabled but email alerts are disabled. Generating empty frames.")

            if config.camera_enabled:
