            yield (b'--frame\r\n'
                   b'Content-Type: image/jpeg\r\n\r\n' + frame.tobytes() + b'\r\n')
        except Exception as e:
            logging.error(f"Error generating frames: {e}")


def main():
    """Initializes the camera and starts the web service."""
    global config, camera, start_time

    try:
        config.load_config()
        config.setup_logging()

        if config.camera_enabled:
            camera = config.get_camera()
            start_time = time.time()
            socketio.run(app, host=config.HOST, port=config.PORT, debug=config.DEBUG, use_reloader=False,
                         background_thread=True)
        else:
            app.run(host=config.HOST, port=config.PORT, debug=config.DEBUG, use_reloader=False)
    except Exception as e:
        logging.critical(f"Fatal error: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    import json
    import threading
    from picamera import PiCamera

    start_time = time.time()
    camera = None

    try:
        main()
    except KeyboardInterrupt:
        logging.info("Shutting down gracefully...")
