from typing import Callable, Tuple, Any

import cv2
import numpy as np
from flask import Flask, render_template, Response, request
from flask_socketio import SocketIO, emit
from werkzeug.utils import secure_filename

# Project-specific modules
try:
    import config
    from predict import Predictor  # noqa: F401
except ImportError as e:
    print(f"Error importing necessary modules: {e}")
    exit(1)


# Configure logging
logging.basicConfig(level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
DEFAULT_CLASSIFIER = "motion_detector"
LIVING_STYLE_GUIDE = "https://github.com/kevinkahn/soft-microscope-wildlife-classifier/blob/main/README.md#getting-started-with-your-own-model"
MODEL_URL = "https://github.com/kevinkahn/soft-microscope-wildlife-classifier/releases/download/v1.0/model.caffemodel"
IMAGE_DILATION_SCALE = 1.2
JPEG_QUALITY = 90
DISPLAY_INFO_COLOR = (255, 255, 255)
SMALL_FONT = 14
MEDIUM_FONT = 20
LARGE_FONT = 40
FACE_DETECTION_SCALE_Y = 1.8
FACE_DETECTION_SCALE_X = 1.7

app = Flask(__name__)
socketio = SocketIO(app, async_mode='threading')

# Global variables
classifier = None
frame = None
output_frame = None
model_loaded = False
last_epoch = 0
last_email_send = datetime.datetime.now()
email_alert_active = False
email_recipient = ""
email_send_interval = 0

# Add a cleanup function to atexit
def cleanup():
    """Releases resources and stops the camera."""
    logging.info("Cleaning up resources...")
    if 'camera' in locals():
        camera.stop_preview()
        camera.close()
    socketio.stop_background_task()
    socketio.server.shutdown()  # More robust shutdown
    logging.info("Cleanup complete.")


atexit.register(cleanup)


def detect_faces(frame: np.ndarray, scale_factor: float = FACE_DETECTION_SCALE_Y) -> Tuple[np.ndarray, float]:
    """Detects faces in a frame using Haar cascades.

    Args:
        frame: The input frame.
        scale_factor: The scale factor for the cascade classifier.

    Returns:
        A tuple containing the locations of the detected faces and the confidence threshold.
    """
    gray_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    gray_frame = cv2.equalizeHist(gray_frame)
    face_cascade = cv2.CascadeClassifier(config.HAAR_CASCADE_PATH)
    results = face_cascade.detectMultiScale(gray_frame, scaleFactor=scale_factor, minNeighbors=5)
    return results, gray_frame.max()


def detect_object(classifier_name: str, frame: np.ndarray) -> Tuple[Any, float]:
    """Detects objects in a frame using a given classifier.

    Args:
        classifier_name: The name of the classifier to use.
        frame: The input frame.

    Returns:
        The detected object and its confidence score.
    """
    global model_loaded, last_epoch

    if not model_loaded:
        logging.error("Model not loaded. Cannot detect objects.")
        return None, 0.0

    try:
        if classifier_name == "motion_detector":
            return detect_motion(frame)
        else:
            return classifier.predict(frame, model_name=classifier_name)
    except Exception as e:
        logging.error(f"Error detecting objects: {e}")
        return None, 0.0


def detect_motion(frame: np.ndarray) -> Tuple[Any, float]:
    """Detects motion in a frame using a background subtractor.

    Args:
        frame: The input frame.

    Returns:
        The detected motion and its confidence score.
    """
    global last_epoch, frame

    if frame is None:
        return [], 0.0

    height, width, _ = frame.shape
    cv2.accumulateWeighted(frame, last_frame, 0.5)
    frame_delta = cv2.absdiff(frame, cv2.convertScaleAbs(last_frame))
    thresh = cv2.threshold(frame_delta, 25, 255, cv2.THRESH_BINARY)[1]
    thresh = cv2.dilate(thresh, None, iterations=2)
    contours, _ = cv2.findContours(thresh.copy(), cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)

    motion_detected = len(contours) > 0
    confidence = np.mean([cv2.boundingRect(c).area for c in contours]) / (float(width) * height)

    last_epoch = time.time()
    return contours, confidence


def process_frame(frame: np.ndarray) -> np.ndarray:
    """Processes a single frame, performing object detection and drawing annotations.

    Args:
        frame: The input frame.

    Returns:
        The processed frame with annotations.
    """
    global classifier, frame, output_frame

    if frame is None:
        return frame.copy()

    results, confidence = detect_object(config.CLASSIFIERS[config.current_classifier], frame)

    if results is not None:
        for (x, y, w, h), detected in results:
            label = config.labels[config.current_classifier] if config.current_classifier in config.labels else ""
            color = DISPLAY_INFO_COLOR
            if label == "person":
                label = "Person"
                color = (0, 255, 225)
            elif label == "car":
                label = "Car"
                color = (0, 0, 255)
            elif label == "bird":
                label = "Bird"
                color = (255, 255, 0)
            elif label == "dog":
                label = "Dog"
                color = (255, 0, 0)

            cv2.rectangle(frame, (x, y), (x + w, y + h), color, 2)
            cv2.putText(frame, label, (x, y - 10), cv2.FONT_HERSHEY_SIMPLEX, SMALL_FONT, color, 2)

    if config.current_classifier == "motion_detector" and config.send_email_alerts:
        contours, confidence = detect_motion(frame)
        if len(contours) > 10 and (time.time() - last_epoch) > int(
                config.email_send_interval * 3600):  # Check every hour
            send_email_alert(contours, confidence)
            last_epoch = time.time()

    if config.current_classifier == "motion_detector" and config.camera_enabled:
        frame = cv2.resize(frame, (frame.shape[1] // IMAGE_DILATION_SCALE, frame.shape[0] // IMAGE_DILATION_SCALE))

    if config.display_info:
        cv2.putText(frame, f"{config.classifier_names[config.current_classifier]:16s} {config.current_classifier}",
                    (10, 20), cv2.FONT_HERSHEY_SIMPLEX, MEDIUM_FONT, (255, 255, 0), 2)
        cv2.putText(frame, f"Det/Conf:{confidence:.2f}", (10, 60), cv2.FONT_HERSHEY_SIMPLEX, SMALL_FONT,
                    (255, 255, 0), 2)

    if config.display_fps:
        cv2.putText(frame, f"{1 / (time.time() - start_time):.1f} FPS", (30, 80), cv2.FONT_HERSHEY_SIMPLEX, LARGE_FONT,
                    (0, 0, 255), 2)

    if config.display_info and config.camera_enabled:
        frame = cv2.resize(frame, (frame.shape[1] * IMAGE_DILATION_SCALE, frame.shape[0] * IMAGE_DILATION_SCALE))

    return frame


def send_email_alert(contours: list, confidence: float) -> None:
    """Sends an email alert when motion is detected.

    Args:
        contours: The detected contours.
        confidence: The confidence score.
    """
    try:
        if not email_alert_active:
            return

        subject = "Motion detected!"
        body = f"Motion detected at {time.strftime('%Y-%m-%d %H:%M:%S')}. Confidence: {confidence:.2f}. Contours: {len(contours)}. Image attached."
        recipient = email_recipient
        send_email(subject, body, recipient)
    except Exception as e:
        logging.error(f"Error sending email: {e}")


def send_email(subject: str, body: str, recipient: str) -> None:
    """Sends an email with the given subject and body.

    Args:
        subject: The email subject.
        body: The email body.
        recipient: The recipient email address.
    """
    try:
        with open(config.EMAIL_ACCOUNTS_FILE, "r") as f:
            sender_address = f.readline().strip()
        logging.info(f"Sending email to {recipient} from {sender_address}: {subject} {body}")
        msg = Message(sender_address, recipients=[recipient], subject=subject)
        msg.body = body
        mail.send(msg)
    except Exception as e:
        logging.error(f"Error sending email: {e}")


def check_for_objects():
    """Continuously checks for objects in the camera feed."""
    global frame, classifier, config, model_loaded, email_alert_active, email_recipient, config

    while True:
        try:
            if config.camera_enabled:
                frame_np = camera.capture_array()
                if frame_np is None:
                    logging.warning("Failed to capture frame from camera.")
                    time.sleep(0.1)  # Prevent busy-waiting
                    continue

                frame_np = cv2.resize(frame_np, (frame.shape[1], frame.shape[0]))
                frame_np = process_frame(frame_np)
                frame = frame_np.copy()

                if config.send_email_alerts and email_alert_active and (
                        time.time() - last_epoch > int(config.email_send_interval * 3600)):
                    contours, confidence = detect_motion(frame)
