    },
    'DHT11': {
        'CHECKSUM_ERROR_THRESHOLD': 3
    },
    'Voice_Recognition': {
        'WAKE_WORD': 'Greenhouse',
        'LISTENING_TIMEOUT': 5
    }
}

# Global variables
config = None
dht11_sensor = None
light_relay = None
camera = None
audio_input = None
stop_event = threading.Event()

# Custom exception classes
class SensorReadError(Exception):
    pass

class GPIOInitializationError(Exception):
    pass

class CameraError(Exception):
    pass

class AudioError(Exception):
    pass

# Logging setup
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def load_configuration(config_file):
    """Loads configuration from the specified file."""
    global config
    config = configparser.ConfigParser()
    config.read(config_file)

    # Load default values if the config file is missing or incomplete
    for section, defaults in DEFAULT_CONFIG.items():
        if not config.has_section(section):
            config[section] = {}
        for key, value in defaults.items():
            if not config.has_option(section, key):
                config[section][key] = str(value)

    # Convert all values to integers or floats where appropriate
    try:
        config['GPIO']['DHT11_PIN'] = int(config['GPIO']['DHT11_PIN'])
        config['GPIO']['LIGHT_RELAY_PIN'] = int(config['GPIO']['LIGHT_RELAY_PIN'])
        config['Camera']['CAMERA_WIDTH'] = int(config['Camera']['CAMERA_WIDTH'])
        config['Camera']['CAMERA_HEIGHT'] = int(config['Camera']['CAMERA_HEIGHT'])
        config['Voice_Recognition']['LISTENING_TIMEOUT'] = int(config['Voice_Recognition']['LISTENING_TIMEOUT'])
    except ValueError as e:
        logging.error(f"Invalid value in config file: {e}. Using default value.")

    # Set log level from config
    log_level = config['Logging']['LOG_LEVEL'].upper()
    logging.getLogger().setLevel(log_level)

def initialize_gpio():
    """Initializes GPIO pins for the light relay."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(config['GPIO']['LIGHT_RELAY_PIN'], GPIO.OUT)
        GPIO.output(config['GPIO']['LIGHT_RELAY_PIN'], GPIO.LOW)  # Initialize to OFF
        logging.info("GPIO initialized successfully.")
    except Exception as e:
        logging.error(f"Failed to initialize GPIO: {e}")
        raise GPIOInitializationError(f"Failed to initialize GPIO: {e}")

def initialize_dht11():
    """Initializes the DHT11 sensor."""
    global dht11_sensor
    try:
        import dht11
        dht11_sensor = dht11.DHT11(pin=config['GPIO']['DHT11_PIN'])
        logging.info("DHT11 sensor initialized successfully.")
    except ImportError:
        logging.error("dht11 library not found. Simulating sensor data.")
        dht11_sensor = None
    except Exception as e:
        logging.error(f"Failed to initialize DHT11 sensor: {e}")
        dht11_sensor = None

def initialize_camera():
    """Initializes the Raspberry Pi camera module."""
    global camera
    try:
        from picamera2 import Picamera2
        camera = Picamera2()
        camera.configure(camera.create_preview_configuration(main={"format": 'XRGB8888', "size": (config['Camera']['CAMERA_WIDTH'], config['Camera']['CAMERA_HEIGHT'])}))
        camera.start()
        logging.info("Camera initialized successfully.")
    except ImportError:
        logging.error("picamera2 library not found. Simulating camera functionality.")
        camera = None
    except Exception as e:
        logging.error(f"Failed to initialize camera: {e}")
        camera = None

def initialize_audio():
    """Initializes the audio input for voice recognition."""
    global audio_input
    try:
        import pyaudio
        import speech_recognition as sr
        audio_input = sr.Microphone()
        logging.info("Audio input initialized successfully.")
    except ImportError:
        logging.error("pyaudio or speech_recognition libraries not found. Simulating audio input.")
        audio_input = None
    except Exception as e:
        logging.error(f"Failed to initialize audio input: {e}")
        audio_input = None

def read_temperature():
    """Reads temperature and humidity from the DHT11 sensor."""
    if dht11_sensor is None:
        # Simulate sensor data if the sensor is not available
        temperature = random.uniform(15, 35)
        humidity = random.uniform(40, 80)
        logging.warning("Simulating temperature and humidity data.")
        return temperature, humidity

    retries = 0
    while retries < 3:
        try:
            result = dht11_sensor.read()
            if result.is_valid():
                temperature = result.temperature
                humidity = result.humidity
                checksum_error_count = result.checksum_error_count
                if checksum_error_count > config['DHT11']['CHECKSUM_ERROR_THRESHOLD']:
                    logging.warning("DHT11 checksum error detected. Discarding reading.")
                    retries += 1
                    time.sleep(1)
                    continue
                return temperature, humidity
            else:
                logging.warning(f"DHT11 reading invalid. Retrying in 1 second. Attempt {retries + 1}")
                retries += 1
                time.sleep(1)
        except Exception as e:
            logging.error(f"Error reading DHT11 sensor: {e}")
            retries += 1
            time.sleep(1)

    logging.error("Failed to read DHT11 sensor after multiple retries.")
    return None, None

def turn_lights_on():
    """Turns on the greenhouse lights."""
    try:
        GPIO.output(config['GPIO']['LIGHT_RELAY_PIN'], GPIO.HIGH)
        logging.info("Lights turned ON.")
    except Exception as e:
        logging.error(f"Error turning lights ON: {e}")

def turn_lights_off():
    """Turns off the greenhouse lights."""
    try:
        GPIO.output(config['GPIO']['LIGHT_RELAY_PIN'], GPIO.LOW)
        logging.info("Lights turned OFF.")
    except Exception as e:
        logging.error(f"Error turning lights OFF: {e}")

def take_picture():
    """Takes a picture using the Raspberry Pi camera."""
    if camera is None:
        logging.warning("Camera is not available. Simulating picture taking.")
        return

    try:
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        filename = f"greenhouse_{timestamp}.jpg"
        camera.capture_file(filename)
        logging.info(f"Picture saved as {filename}")
    except Exception as e:
        logging.error(f"Error taking picture: {e}")

def listen_for_command():
    """Listens for voice commands and executes them."""
    if audio_input is None:
        logging.warning("Audio input is not available. Cannot listen for commands.")
        return

    r = sr.Recognizer()
    with audio_input as source:
        r.adjust_for_ambient_noise(source)  # Adjust for background noise
        try:
            audio = r.listen(source, timeout=config['Voice_Recognition']['LISTENING_TIMEOUT'])
        except sr.WaitTimeoutError:
            logging.warning("No speech detected within the timeout period.")
            return

    try:
        # Use Google Web Speech API for voice recognition
        command = r.recognize_google(audio).lower()
        logging.info(f"Recognized command: {command}")
        return command
    except sr.UnknownValueError:
        logging.warning("Could not understand audio")
        return None
    except sr.RequestError as e:
        logging.error(f"Could not request results from Google Web Speech API; {e}")
        return None

def process_command(command):
    """Processes the recognized voice command."""
    if command is None:
        return

    logging.info(f"Processing command: {command}")
    if "turn on the lights" in command:
        turn_lights_on()
    elif "turn off the lights" in command:
        turn_lights_off()
    elif "what is the temperature" in command:
        temperature, humidity = read_temperature()
        if temperature is not None and humidity is not None:
            print(f"Temperature: {temperature:.2f} °C, Humidity: {humidity:.2f} %")
        else:
            print("Failed to read temperature and humidity.")
    elif "take a picture" in command:
        take_picture()
    else:
        print("Unknown command.")

def signal_handler(sig, frame):
    """Handles signals for graceful shutdown."""
    logging.info("Received signal, shutting down...")
    stop_event.set()
    GPIO.cleanup()
    if camera:
        camera.close()
    logging.info("Shutdown complete.")
    exit(0)

def main():
    """Main function to run the greenhouse control system."""
    global stop_event

    # Load configuration
    load_configuration(CONFIG_FILE)

    # Initialize components
    try:
        initialize_gpio()
        initialize_dht11()
        initialize_camera()
        initialize_audio()
    except (GPIOInitializationError, SensorReadError, CameraError, AudioError) as e:
        logging.error(f"Initialization failed: {e}")
        print(f"Initialization failed: {e}")
        GPIO.cleanup()
        exit(1)

    # Set up signal handler
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    logging.info("Greenhouse control system started.")

    # Main loop
    try:
        while not stop_event.is_set():
            command = listen_for_command()
            if command:
                process_command(command)
            time.sleep(0.1)  # Reduce CPU usage
    except KeyboardInterrupt:
        # Handle Ctrl+C gracefully
        logging.info("Keyboard interrupt detected.")
    finally:
        # Clean up resources before exiting
        GPIO.cleanup()
        if camera:
            camera.close()
        logging.info("Greenhouse control system stopped.")

if __name__ == "__main__":
    main()

