import time
import cv2
import numpy as np

# Configuration
MOTION_THRESHOLD = 10
CAPTURE_INTERVAL = 2  # seconds
CAMERA_WARM_UP = 2  # seconds
CAMERA_FRAMERATE = 15

def initialize_camera():
    """Initializes the CSI camera and returns the capture object."""
    try:
        cap = cv2.VideoCapture(0)
        if not cap.isOpened():
            raise IOError("Cannot open CSI camera.")
        return cap
    except IOError as e:
        print(f"Error initializing camera: {e}")
        return None

def capture_frame(cap):
    """Captures a single frame from the CSI camera."""
    ret, frame = cap.read()
    if not ret:
        print("Failed to capture frame.")
        return None
    return frame

def calculate_average_pixel_value(frame):
    """Calculates the average pixel value of a frame."""
    return np.mean(frame)

def detect_motion(current_avg, baseline_avg, threshold):
    """Detects motion based on the difference between current and baseline average pixel values."""
    return abs(current_avg - baseline_avg) > threshold

def save_frame(frame, filename="motion.jpg"):
    """Saves the captured frame to a file."""
    try:
        cv2.imwrite(filename, frame)
        print(f"Motion detected! Image saved as {filename}")
    except Exception as e:
        print(f"Error saving image: {e}")

def update_baseline(frame):
    """Updates the baseline average pixel value."""
    return calculate_average_pixel_value(frame)

def main():
    """Main function to continuously monitor the CSI camera for motion."""
    cap = initialize_camera()
    if cap is None:
        return

    baseline_avg = None
    try:
        # Camera warm-up
        print("Warming up camera...")
        time.sleep(CAMERA_WARM_UP)

        while True:
            frame = capture_frame(cap)
            if frame is None:
                break

            current_avg = calculate_average_pixel_value(frame)

            if baseline_avg is not None and detect_motion(current_avg, baseline_avg, MOTION_THRESHOLD):
                save_frame(frame)
                baseline_avg = update_baseline(frame)  # Update baseline after motion detection
            else:
                baseline_avg = update_baseline(frame)  # Update baseline even if no motion

            time.sleep(CAPTURE_INTERVAL)

    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        # Release resources
        if cap:
            cap.release()
            print("Camera resources released.")

if __name__ == "__main__":
    main()

