import pyzbar.pyzbar as pyzbar
import datetime
import csv
import os
import time
import threading
import logging

# Configure logging
logging.basicConfig(filename='error_log.txt', level=logging.ERROR,
                    format='%(asctime)s - %(levelname)s - %(message)s')

# Define the CSV file name
CSV_FILE = 'inventory_log.csv'

# Define the camera index
CAMERA_INDEX = 0

# Define the QR code validation pattern
VALID_CHARACTERS = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'

def initialize_camera():
    """Initializes the USB camera and returns the capture object."""
    try:
        cap = cv2.VideoCapture(CAMERA_INDEX)
        if not cap.isOpened():
            raise IOError("Cannot open webcam")
        return cap
    except IOError as e:
        logging.error(f"Camera initialization failed: {e}")
        return None

def decode_qr_code(frame):
    """Decodes QR codes in a frame and returns the decoded string."""
    try:
        decoded_objects = pyzbar.decode(frame)
        if decoded_objects:
            return decoded_objects[0].data.decode('utf-8')
        return None
    except Exception as e:
        logging.error(f"QR code decoding failed: {e}")
        return None

def validate_data(data):
    """Validates the decoded data to ensure it contains only letters and digits."""
    if not data:
        return False
    for char in data:
        if not char.isalnum():
            return False
    return True

def log_data(item_id):
    """Logs the item identifier to the CSV file."""
    try:
        with open(CSV_FILE, 'a', newline='') as csvfile:
            fieldnames = ['timestamp', 'item_id']
            writer = csv.DictWriter(csvfile, fieldnames=fieldnames)
            if csvfile.tell() == 0:  # Check if the file is empty to write the header
                writer.writeheader()
            writer.writerow({'timestamp': datetime.datetime.now().isoformat(), 'item_id': item_id})
    except Exception as e:
        logging.error(f"Data logging failed: {e}")

def capture_and_process():
    """Captures frames from the camera, decodes QR codes, and logs data."""
    cap = initialize_camera()
    if cap is None:
        return

    try:
        while True:
            ret, frame = cap.read()
            if not ret:
                logging.error("Failed to capture frame")
                break

            decoded_data = decode_qr_code(frame)
            if decoded_data:
                if validate_data(decoded_data):
                    log_data(decoded_data)
                    print(f"Decoded item ID: {decoded_data}")
                else:
                    logging.error(f"Invalid data: {decoded_data}")
            time.sleep(0.2)  # Adjust as needed
    finally:
        cap.release()
        cv2.destroyAllWindows()

if __name__ == "__main__":
    try:
        capture_and_process()
    except KeyboardInterrupt:
        print("Exiting program")
    except Exception as e:
        logging.error(f"Unhandled exception: {e}")

