import time
import logging
import signal
import sys

import cv2
import numpy as np
import RPi.GPIO as GPIO
import sounddevice as sd
from gpiozero import Button

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Constants
POSITIVE_LABEL = "POSITIVE"
POSITIVE_THRESHOLD = 0.7
CONFIG_FILE = "config.TRAINING_FILE"
CASENAME = "CASE_SWITCH"

# GPIO pin configuration
DOOR_LOCK_PIN = 18
BUTTON_PIN = 17

# Global variables
info = None
model = None
button = None
sound_pool = {}


def load_config(config_file):
    """Loads configuration from a file."""
    try:
        with open(config_file, "rb") as f:
            return f.read()
    except FileNotFoundError:
        logger.error(f"Configuration file not found: {config_file}")
        sys.exit(1)
    except Exception as e:
        logger.error(f"Error loading configuration: {e}")
        sys.exit(1)


def initialize_gpio(lock_pin, button_pin):
    """Initializes GPIO pins."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(lock_pin, GPIO.OUT, initial=GPIO.HIGH)
        GPIO.setup(button_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    except Exception as e:
        logger.error(f"GPIO initialization failed: {e}")
        sys.exit(1)


def initialize_camera(face_cascade):
    """Initializes the camera."""
    try:
        camera = cv2.VideoCapture(0)
        if not camera.isOpened():
            raise RuntimeError('Could not start camera.')
        return camera
    except Exception as e:
        logger.error(f"Camera initialization failed: {e}")
        sys.exit(1)


def initialize_sound(config):
    """Initializes sound files."""
    global sound_pool
    sound_pool = {}
    try:
        fs = config.SAMPLERATE
        for name, data in config.sound_files.items():
            sound_pool[name] = sd.Sound(data, samplerate=fs)
    except Exception as e:
        logger.error(f"Sound initialization failed: {e}")
        sys.exit(1)


def initialize_model(config):
    """Initializes the face recognition model."""
    global model
    try:
        model = cv2.face.EigenFaceRecognizer_create()
        model.read(config.TRAINING_FILE)
    except Exception as e:
        logger.error(f"Model initialization failed: {e}")
        sys.exit(1)


def get_camera_image(camera):
    """Captures an image from the camera."""
    try:
        ret, frame = camera.read()
        if not ret:
            raise RuntimeError("Could not read frame")
        return frame
    except Exception as e:
        logger.error(f"Error capturing image: {e}")
        return None


def detect_face(frame, face_cascade):
    """Detects a single face in the frame."""
    try:
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        return face_cascade.detectMultiScale(gray, 1.3, 5)
    except Exception as e:
        logger.error(f"Face detection failed: {e}")
        return []


def crop_face(frame, x, y, w, h):
    """Crops the face region from the frame."""
    try:
        height = int((y + h) - (y + h) % 8)
        face = frame[y:y + h, x:x + w]
        return cv2.resize(face, (100, 100))
    except Exception as e:
        logger.error(f"Face cropping failed: {e}")
        return None


def predict(face):
    """Predicts the label of the given face."""
    try:
        label, confidence = model.predict(face)
        return label, confidence
    except Exception as e:
        logger.error(f"Prediction failed: {e}")
        return None, None


def play_sound(label):
    """Plays the corresponding sound."""
    try:
        if label == POSITIVE_LABEL:
            sound_pool[POSITIVE_LABEL].play()
        else:
            sound_pool[CASENAME].play()
            time.sleep(0.2)
            sound_pool[NEGATIVE_LABEL].play()
            time.sleep(0.2)
    except Exception as e:
        logger.error(f"Sound playback failed: {e}")


def unlock_door(lock_pin):
    """Unlocks the door."""
    try:
        GPIO.output(lock_pin, GPIO.LOW)
        logger.info("Door unlocked")
    except Exception as e:
        logger.error(f"Door unlock failed: {e}")


def lock_door(lock_pin):
    """Locks the door."""
    try:
        GPIO.output(lock_pin, GPIO.HIGH)
        logger.info("Door locked")
    except Exception as e:
        logger.error(f"Door lock failed: {e}")


def handle_button_press(lock_pin, button):
    """Handles button press event."""
    if button.is_pressed:
        logger.info("Button pressed")
        unlock_door(lock_pin)


def main_loop(camera, lock_pin, button_pin, config):
    """Main loop for face recognition and door control."""
    try:
        while True:
            if button.is_pressed:
                handle_button_press(lock_pin, button)
            else:
                frame = get_camera_image(camera)
                if frame is None:
                    time.sleep(0.1)
                    continue
                faces = detect_face(frame, cv2.CascadeClassifier(config.face_cascade_path))
                if len(faces) == 1:
                    x, y, w, h = faces[0]
                    face = crop_face(frame, x, y, w, h)
                    if face is None:
                        time.sleep(0.1)
                        continue
                    label, confidence = predict(face)
                    if label == POSITIVE_LABEL and confidence < POSITIVE_THRESHOLD:
                        logger.info("Recognized")
                        play_sound(label)
                        unlock_door(lock_pin)
                    else:
                        logger.info("Not recognized")
                        play_sound(CASENAME)
                        time.sleep(0.2)
                        play_sound(NEGATIVE_LABEL)
                        time.sleep(0.2)
                else:
                    logger.info("No face detected")
                    play_sound(CASENAME)
