import cv2
import sys
from contextlib import contextmanager

@contextmanager
def open_camera(driver, resolution, format):
    """Context manager for opening and releasing the camera."""
    try:
        camera = driver.create_camera(resolution, format)
        yield camera
    finally:
        camera.release()

def convert_to_bgr(frame, format):
    """Converts the frame to BGR format."""
    if format == "XRGB8888":
        return frame[:, :, (0, 1, 2)]
    else:
        raise ValueError("Unsupported color format")

def convert_to_gray(frame, format):
    """Converts the frame to grayscale."""
    if format == "XRGB8888":
        return cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    else:
        raise ValueError("Unsupported color format")

def detect_faces(frame, cascade_path):
    """Detects faces in the given frame."""
    try:
        detector = cv2.CascadeClassifier(cascade_path)
        gray = convert_to_gray(frame, "XRGB8888")
        faces = detector.detectMultiScale(gray, 1.3, 5)
        return faces
    except Exception as e:
        print(f"Error detecting faces: {e}")
        return []

def draw_rectangles(frame, faces):
    """Draws rectangles around the detected faces."""
    for (x, y, w, h) in faces:
        cv2.rectangle(frame, (x, y), (x + w, y + h), (0, 255, 0), 2)
    return frame

def main():
    """Main function to capture video and detect faces."""
    cascade_path = "haarcascade_frontalface_default.xml"  # Replace with your path if needed
    if not cv2.CascadeClassifier.is_loaded(cascade_path):
        raise FileNotFoundError(f"Cascade classifier not found at {cascade_path}")

    video_capture = None
    try:
        with open_camera("driver", (640, 480), "XRGB8888") as video_capture:
            cv2.namedWindow("Face Detection", cv2.WINDOW_AUTOSIZE)
            while True:
                frame = video_capture.read()
                if frame is None:
                    break  # Handle potential camera read errors

                bgr_frame = convert_to_bgr(frame, "XRGB8888")
                faces = detect_faces(bgr_frame, cascade_path)
                frame_with_rectangles = draw_rectangles(bgr_frame, faces)

                cv2.imshow("Face Detection", frame_with_rectangles)

                if cv2.waitKey(1) & 0xFF == ord('q'):
                    break

    except KeyboardInterrupt:
        print("\nExiting...")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        if video_capture is not None:  # Ensure video_capture is initialized before attempting to release
            video_capture.release()
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

