import smbus
import time
import os

# I2C bus number on the Raspberry Pi (usually 1)
I2C_BUS_NUMBER = 1

# Thermal zone file path on the Raspberry Pi
THERMAL_ZONE_FILE = "/sys/class/thermal/thermal_zone0/temp"


def read_temperature_celsius():
    """Read the CPU temperature in Celsius from the thermal zone file."""
    try:
        with open(THERMAL_ZONE_FILE, "r") as temp_file:
            raw_temperature = temp_file.read().strip()
            temperature_celsius = float(raw_temperature) / 1000.0
            return temperature_celsius
    except (FileNotFoundError, PermissionError) as temp_error:
        print(f"Error reading temperature: {temp_error}")
        return None
    except ValueError as value_error:
        print(f"Invalid temperature value: {value_error}")
        return None


def initialize_i2c_bus(bus_number):
    """Initialize the I2C bus."""
    try:
        bus = smbus.SMBus(bus_number)
        return bus
    except OSError as bus_error:
        print(f"Error initializing I2C bus: {bus_error}")
        return None


def display_temperature(temperature):
    """Print the temperature to the console."""
    if temperature is not None:
        print(f"Current CPU temperature: {temperature:.1f} °C")


def main():
    """Main function to read and display the CPU temperature."""
    i2c_bus = initialize_i2c_bus(I2C_BUS_NUMBER)
    if i2c_bus is None:
        return

    try:
        while True:
            temperature = read_temperature_celsius()
            display_temperature(temperature)
            time.sleep(2)
    except KeyboardInterrupt:
        print("Temperature monitoring stopped.")
    finally:
        # No explicit I2C bus closing needed with 'with' statement,
        # but including a placeholder for completeness.
        pass


if __name__ == "__main__":
    main()

