import serial
import time

# Configure the serial port for the thermal printer
def configure_printer(port, baud_rate, bytesize, parity, stopbits, timeout):
    try:
        printer = serial.Serial(port, baud_rate, bytesize=bytesize, parity=parity, stopbits=stopbits, timeout=timeout)
        return printer
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

# Format the temperature data as a receipt line
def format_receipt_line(celsius, fahrenheit):
    return f"Temperature: {celsius:.2f}C / {fahrenheit:.2f}F\n"

# Print the receipt to the thermal printer
def print_receipt(printer, receipt_lines):
    try:
        for line in receipt_lines:
            printer.write(line.encode())
            time.sleep(0.5)
    except serial.SerialException as e:
        print(f"Error writing to serial port: {e}")

# Main function to read temperature and print receipt
def main():
    # Configure the serial port for the thermal printer
    printer = configure_printer(port="/dev/ttyUSB0", baud_rate=9600, bytesize=8, parity=serial.PARITY_NONE, stopbits=1, timeout=1)

    if printer is None:
        print("Failed to configure printer. Exiting.")
        return

    try:
        # Simulate reading temperature data
        temperature_celsius = 25.0
        temperature_fahrenheit = temperature_celsius * 9/5 + 32

        # Format the receipt line
        receipt_line = format_receipt_line(temperature_celsius, temperature_fahrenheit)

        # Print the receipt
        print_receipt(printer, [receipt_line])

        print("Receipt printed successfully.")

    except KeyboardInterrupt:
        print("Script interrupted. Exiting...")
    finally:
        if printer:
            printer.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

