# -*- coding: utf-8 -*-
"""AHT20 sensor reader for Raspberry Pi 5.

Reads temperature and humidity from an AHT20 sensor over I2C and prints the readings.

Error handling is implemented to manage sensor detection failures, I2C communication
problems, and invalid readings. The program attempts to recover from errors where possible
and provides informative error messages.
"""

import time
import board
import busio
import adafruit_ahtx0

# Constants
READ_INTERVAL_SECONDS = 5
TEMPERATURE_MIN_C = -40
TEMPERATURE_MAX_C = 85
HUMIDITY_MIN_PERCENT = 0
HUMIDITY_MAX_PERCENT = 100


def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None


def initialize_ahtx0(i2c_bus):
    """Initialize the AHTx0 sensor."""
    try:
        return adafruit_ahtx0.AHTx0(i2c_bus)
    except Exception as e:
        print(f"Error initializing AHTx0 sensor: {e}")
        return None


def read_sensor_data(sensor):
    """Read temperature and humidity from the sensor."""
    try:
        temperature = sensor.temperature
        humidity = sensor.relative_humidity
        return temperature, humidity
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None


def validate_data(temperature, humidity):
    """Validate temperature and humidity readings."""
    if temperature is None or humidity is None:
        return False
    if not (TEMPERATURE_MIN_C <= temperature <= TEMPERATURE_MAX_C):
        print(f"Warning: Invalid temperature reading: {temperature}°C")
        return False
    if not (HUMIDITY_MIN_PERCENT <= humidity <= HUMIDITY_MAX_PERCENT):
        print(f"Warning: Invalid humidity reading: {humidity}%")
        return False
    return True


def format_output(temperature, humidity):
    """Format the output string."""
    return f"Temperature: {temperature:.1f} C\nHumidity: {humidity:.1f} %"


def print_header():
    """Print the header for the output."""
    print("Sensor Reading\n--------------")


def main():
    """Main function to read and print sensor data."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    sensor = initialize_ahtx0(i2c_bus)
    if sensor is None:
        return

    try:
        while True:
            print_header()
            temperature, humidity = read_sensor_data(sensor)

            if validate_data(temperature, humidity):
                output = format_output(temperature, humidity)
                print(output)

            time.sleep(READ_INTERVAL_SECONDS)

    except KeyboardInterrupt:
        print("Exiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # No specific resources to clean up in this case, but included for potential future expansion.
        i2c_bus.deinit()  # Release I2C resources


if __name__ == "__main__":
    main()

