import time
import datetime
import Adafruit_DHT
import RPi.GPIO as GPIO

# DHT22 sensor configuration for the Raspberry Pi
DHT_SENSOR = Adafruit_DHT.DHT22
DHT_PIN = 17
READ_INTERVAL_SECONDS = 2

def read_dht22_data():
    """Read temperature and humidity from the DHT22 sensor."""
    try:
        humidity, temperature = Adafruit_DHT.read_retry(DHT_SENSOR, DHT_PIN)
        if humidity is not None and temperature is not None:
            return round(temperature, 1), round(humidity, 1)
        return None, None
    except RuntimeError as read_error:
        print("DHT22 read error:", read_error)
        return None, None
    except Exception as sensor_error:
        print("Unexpected sensor error:", sensor_error)
        return None, None

def format_measurement(temperature_value, humidity_value):
    """Format the measurement as an ISO-8601 timestamped string."""
    timestamp_text = datetime.datetime.now().isoformat()
    return timestamp_text + " Temp: " + str(temperature_value) + "°C Humidity: " + str(humidity_value) + "%"

def main():
    """Main entry point for the Raspberry Pi temperature and humidity monitor."""
    try:
        while True:
            temperature_value, humidity_value = read_dht22_data()
            if temperature_value is not None and humidity_value is not None:
                formatted_text = format_measurement(temperature_value, humidity_value)
                print(formatted_text)
            time.sleep(READ_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("Stopping temperature monitor")
    finally:
        # No GPIO cleanup needed for Adafruit_DHT library usage
        pass

if __name__ == "__main__":
    main()

