import serial
import time
import numpy as np
import matplotlib.pyplot as plt

# Serial port configuration for the thermal camera
port = "/dev/ttyUSB0"
baud_rate = 9600
timeout = 1

try:
    # Open the serial port
    serial_port = serial.Serial(port, baud_rate, timeout=timeout)
    print("Thermal camera serial port opened successfully.")
except serial.SerialException as e:
    print(f"Error opening serial port: {e}")
    exit()

# Function to fetch a thermal frame from the serial port
def get_thermal_frame():
    """Reads a thermal frame from the serial port and returns it as a NumPy array."""
    try:
        line = serial_port.readline().decode("ascii", errors="replace").strip()
        if line:
            frame_data = [int(value) for value in line.split(",") if value]
            if len(frame_data) == 768:
                return np.array(frame_data).reshape((24, 32))
            else:
                print("Incomplete frame received.")
                return None
        else:
            return None
    except ValueError as e:
        print(f"ValueError: {e}")
        return None
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        return None

# Main loop to continuously read and display the thermal frame
if __name__ == "__main__":
    try:
        plt.ion()  # Turn on interactive mode for non-blocking updates
        fig, ax = plt.subplots()
        thermal_image = ax.imshow(np.zeros((24, 32)), cmap="inferno", interpolation="nearest")  # Initialize with zeros

        while True:
            frame = get_thermal_frame()
            if frame is not None:
                thermal_image.set_data(frame)  # Update the image data
                plt.draw()  # Redraw the plot
                plt.pause(0.1)  # Non-blocking pause

            time.sleep(0.05)  # Reduced sleep time for faster updates

    except KeyboardInterrupt:
        print("Program terminated by user.")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        # Clean up resources
        plt.ioff()  # Turn off interactive mode
        plt.close(fig)
        if serial_port.is_open:
            serial_port.close()
            print("Serial port closed.")
        print("Program finished.")

