#!/usr/bin/python3
# Simple LED control from a switch via MCP23017 on Raspberry Pi 1
# Demonstrates basic I2C GPIO expander interaction for STEM education

import time
from MCP23017_I2C import GPIO_CHIP, MCP23017Error

# MCP23017 I2C address and Raspberry Pi pin assignments
MCP23017_ADDRESS = 0x20
SWITCH_A_GPB = 7
LED_A_GPA = 0
I2C_BUS_NUMBER = 0
POLL_INTERVAL_SECONDS = 0.1


def initialize_gpio(gpio_chip):
    """Configure the MCP23017 chip for the switch and LED."""
    # Set switch pin as input with internal pull-up resistor
    try:
        gpio_chip.setup(SWITCH_A_GPB, 'IN', 'PU')
    except MCP23017Error as error:
        print(f"Setup error: {error}")
        raise
    # Set LED pin as output
    try:
        gpio_chip.setup(LED_A_GPA, 'OUT', 'PU')
    except MCP23017Error as error:
        print(f"Setup error: {error}")
        raise


def read_switch_state(gpio_chip):
    """Read the current state of the mechanical switch."""
    try:
        return gpio_chip.input(SWITCH_A_GPB, 'A')
    except MCP23017Error as error:
        print(f"Read error: {error}")
        return None


def control_led(gpio_chip, led_state):
    """Turn the LED on or off based on the given state."""
    try:
        gpio_chip.output(LED_A_GPA, led_state, 'A')
    except MCP23017Error as error:
        print(f"Output error: {error}")


def main():
    """Main function to continuously mirror switch state to LED."""
    gpio_chip = None
    try:
        gpio_chip = GPIO_CHIP(MCP23017_ADDRESS, I2C_BUS_NUMBER)
        initialize_gpio(gpio_chip)
        previous_state = None
        # Continuously poll the switch and update the LED accordingly
        while True:
            current_state = read_switch_state(gpio_chip)
            if current_state is not None:
                if current_state != previous_state:
                    print('Led ON' if current_state else 'Led OFF')
                    control_led(gpio_chip, current_state)
                    previous_state = current_state
            time.sleep(POLL_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("Exiting program")
    except Exception as error:
        print(f"Unexpected error: {error}")
    finally:
        # Ensure the LED is turned off on exit
        if gpio_chip is not None:
            control_led(gpio_chip, 0)


if __name__ == "__main__":
    main()

