import sys
import threading
import time
import RPi.GPIO as GPIO
import DOGProtocol as DOG  # Replace with your actual DOGProtocol library

# Constants
DEFAULT_LOG_FILE = "data.log"
PROMPT = "JAYES@ROVER53:\t"

# GPIO setup (if needed, otherwise remove or adapt)
GPIO.setmode(GPIO.BOARD)
# Example GPIO setup, adjust to your actual pins
# GPIO.setup(17, GPIO.IN)

# Global variables
log_file_path = DEFAULT_LOG_FILE
receive_thread = None
receive_running = False


def log_message(message):
    """Write a message to the log file."""
    try:
        with open(log_file_path, 'a') as log_file:
            log_file.write(message + "\n")
    except IOError as e:
        print(f"Error writing to log file: {e}")


def receive_loop():
    """Continuously receive data and log it."""
    global receive_running
    while receive_running:
        try:
            data = DOG.receive()  # Your DOGProtocol receive function
            if data:  # Check if data is not empty/None
                log_message(data)
        except Exception as e:
            print(f"Error receiving data: {e}")
            break  # Exit the loop on a critical error
        time.sleep(0.1)  # Add a small delay to avoid excessive CPU usage


def start_logging(log_file):
    """Start the data logging process in a separate thread."""
    global log_file_path, receive_thread, receive_running
    if receive_thread and receive_running:
        return  # Already logging

    log_file_path = log_file
    try:
        with open(log_file_path, 'a'):  # Check if file can be opened/created
            pass
    except IOError as e:
        print(f"Error opening log file: {e}")
        return

    receive_running = True
    receive_thread = threading.Thread(target=receive_loop, name='ReceiveThread', daemon=True)
    receive_thread.start()


def stop_logging():
    """Stop the data logging process."""
    global receive_running, receive_thread
    receive_running = False
    if receive_thread:
        receive_thread.join(timeout=2)  # Wait for thread to finish, but with a timeout
        if receive_thread.is_alive():
            print("Logging thread did not terminate gracefully.")


def send_command(command):
    """Send a command using DOGProtocol."""
    try:
        DOG.send(command)
        print(f"Sent: {command}")
    except Exception as e:
        print(f"Error sending command: {e}")


def display_log():
    """Display the contents of the log file."""
    try:
        with open(log_file_path, 'r') as log_file:
            print(log_file.read())
    except IOError as e:
        print(f"Error reading log file: {e}")


def write_to_log(data):
    """Write a string directly to the log file."""
    if not data:
        return
