import time
import board
import busio
import adafruit_tsl2561
import RPi.GPIO as GPIO

# Configuration constants
LED_GPIO_PIN = 18
PWM_FREQUENCY_HZ = 1000
I2C_SCL_PIN = board.I2C_SDA_PIN
I2C_SDA_PIN = board.I2C_SCL_PIN

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        return busio.I2C(I2C_SCL_PIN, I2C_SDA_PIN)
    except ValueError as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_light_sensor(i2c_bus):
    """Initialize the TSL2561 light sensor."""
    try:
        return adafruit_tsl2561.TSL2561(i2c_bus)
    except ValueError as e:
        print(f"Error initializing TSL2561 sensor: {e}")
        return None

def initialize_led(led_pin, pwm_frequency):
    """Initialize the LED pin with PWM."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(led_pin, GPIO.OUT)
    pwm_led = GPIO.PWM(led_pin, pwm_frequency)
    pwm_led.start(0)
    return pwm_led

def read_ambient_light(sensor_device):
    """Read the ambient light level in lux."""
    try:
        return sensor_device.lux
    except Exception as e:
        print(f"Error reading light sensor: {e}")
        return None

def adjust_led_brightness(pwm_led, light_level):
    """Adjust the LED brightness based on the light level."""
    if light_level is not None:
        brightness_level = min(max(int(light_level / 10), 0), 100)
        pwm_led.ChangeDutyCycle(brightness_level)

def main():
    """Main function to control LED brightness based on ambient light."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    light_sensor = initialize_light_sensor(i2c_bus)
    if light_sensor is None:
        return

    pwm_led = initialize_led(LED_GPIO_PIN, PWM_FREQUENCY_HZ)

    try:
        while True:
            light_level = read_ambient_light(light_sensor)
            if light_level is None:
                time.sleep(1)
                continue

            adjust_led_brightness(pwm_led, light_level)
            time.sleep(1)

    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        # Cleanup resources
        pwm_led.stop()
        GPIO.cleanup()
        i2c_bus.deinit()
        print("GPIO and I2C cleaned up.")

if __name__ == "__main__":
    main()

