import RPi.GPIO as GPIO
import time
import sys

# Define the GPIO pin connected to the fan's PWM control input
FAN_PIN = 12

# PWM frequency in Hz
PWM_FREQUENCY = 25000

# Initialize GPIO settings
GPIO.setmode(GPIO.BCM)
GPIO.setup(FAN_PIN, GPIO.OUT, initial=GPIO.LOW)


def initialize_pwm(pin, frequency):
    """
    Initializes the PWM object for the given pin and frequency.
    Falls back to software PWM if hardware PWM is not available.
    """
    try:
        pwm_instance = GPIO.PWM(pin, frequency)
        pwm_instance.start(0)  # Start with 0% duty cycle
        return pwm_instance
    except Exception as e:
        print(f"Error initializing hardware PWM: {e}")
        return None


def set_fan_speed(fan_pwm, speed_percentage):
    """
    Sets the fan speed to the specified percentage using PWM.
    """
    if fan_pwm is None:
        print("PWM not initialized. Cannot set fan speed.")
        return

    try:
        fan_pwm.ChangeDutyCycle(speed_percentage)
        print(f"Fan speed set to {speed_percentage}%")
    except ValueError as e:
        print(f"Invalid speed value: {e}")
    except Exception as e:
        print(f"Error setting fan speed: {e}")


def main():
    """
    Main function to control the fan speed based on user input.
    """
    fan_pwm = initialize_pwm(FAN_PIN, PWM_FREQUENCY)

    try:
        while True:
            user_input = input("Enter fan speed (0-100) or 'q' to quit: ")
            if user_input.lower() == "q":
                break
            try:
                fan_speed = int(user_input)
                if 0 <= fan_speed <= 100:
                    set_fan_speed(fan_pwm, fan_speed)
                else:
                    print("Invalid speed value. Please enter a value between 0 and 100.")
            except ValueError:
                print("Invalid input. Please enter a number or 'q'.")

    except KeyboardInterrupt:
        print("\nFan control interrupted by keyboard.")
    finally:
        if fan_pwm is not None:
            fan_pwm.stop()  # Stop PWM if it was initialized
        GPIO.cleanup()  # Clean up GPIO settings
        print("GPIO resources released.")


if __name__ == "__main__":
    main()

