# Define GPIO pins for the rotary encoder
CLK_PIN = 17
DT_PIN = 18

# Debounce time in seconds
DEBOUNCE_TIME = 0.005

def setup_gpio(clk_pin, dt_pin):
    """Set up GPIO pins for rotary encoder."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(clk_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.setup(dt_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    except Exception as e:
        raise RuntimeError(f"GPIO setup failed: {e}")


def read_state(pin):
    """Read the current state of a GPIO pin."""
    return GPIO.input(pin)


def rotation_detected(clk_pin, dt_pin, last_state, callback, current_time):
    """Determine rotation direction and call callback."""
    clk_state = read_state(clk_pin)
    dt_state = read_state(dt_pin)

    if current_time - last_state < DEBOUNCE_TIME:
        return last_state, callback  # No rotation yet, return current state

    if clk_state != last_state:
        if dt_state != clk_state:
            rotation = 1
        else:
            rotation = -1

        new_state = rotation  # Update last_state with the detected rotation

        try:
            callback(new_state)
        except Exception as e:
            print(f"Error in callback: {e}")
            # Optionally, log the error or take other actions here.

        return new_state

    return last_state



class RotaryEncoder:
    """
    A class to manage a rotary encoder on a Raspberry Pi.

    Attributes:
        clk_pin (int): GPIO pin for the CLK signal.
        dt_pin (int): GPIO pin for the DT signal.
        callback (callable, optional): Function to call on each rotation. 
                                        Defaults to None.
    """
    def __init__(self, clk_pin, dt_pin, callback=None):
        self.clk_pin = clk_pin
        self.dt_pin = dt_pin
        self.callback = callback
        self.last_state = None
        self.rotation_count = 0

        try:
            setup_gpio(clk_pin, dt_pin)
            GPIO.add_event_detect(self.clk_pin, GPIO.BOTH, callback=self._rotation_detected)
            self.last_state = self.read_state(self.clk_pin) # Initialize last_state
        except Exception as e:
            raise RuntimeError(f"Encoder initialization failed: {e}")


    def read_state(self, pin):
        """Read the current state of a GPIO pin."""
        return GPIO.input(pin)


    def _rotation_detected(self, channel):
        """Internal callback function for GPIO event detection."""
        current_time = time.time()
        self.last_state, self.rotation_count = read_state(self.clk_pin), self.rotation_count + 1
        self.last_state = rotation_detected(self.clk_pin, self.dt_pin, self.last_state, self.callback, current_time)


    def cleanup(self):
        """Remove event detection and reset GPIO settings."""
        GPIO.remove_event_detect(self.clk_pin)  # Remove only the added event detection.

    def get_rotation_count(self):
        """Return the current rotation count."""
        return self.rotation_count

    def set_callback(self, callback):
        """Set the callback function."""
        if callable(callback):  # Check if it's a callable function
            self.callback = callback
        else:
            print("Invalid callback function provided.")


