import time
import requests

# Define GPIO pin for the push button
BUTTON_PIN = 17

# Define the quality dashboard endpoint
DASHBOARD_URL = "http://localhost:8000/quality"

def setup_gpio():
    """Set up the GPIO pin for the button."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(BUTTON_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)

def get_button_state():
    """Read the current state of the button."""
    return GPIO.input(BUTTON_PIN) == GPIO.LOW

def create_quality_report(part_id, passed, defect_count):
    """Create a JSON report for the quality dashboard."""
    report = {
        "part_id": part_id,
        "passed": passed,
        "defect_count": defect_count
    }
    return report

def post_quality_data(report):
    """Post the quality report to the dashboard."""
    try:
        response = requests.post(DASHBOARD_URL, json=report)
        response.raise_for_status()  # Raise HTTPError for bad responses (4xx or 5xx)
        print(f"Quality data sent. Status code: {response.status_code}")
    except requests.exceptions.RequestException as e:
        print(f"Network error: {e}")

def main():
    """Main function to monitor the button and send quality data."""
    setup_gpio()
    part_id = "PART-204"
    try:
        while True:
            if get_button_state():
                report = create_quality_report(part_id, False, 1)
                post_quality_data(report)
            else:
                report = create_quality_report(part_id, True, 0)
                post_quality_data(report)
            time.sleep(2)
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        GPIO.cleanup()  # Clean up GPIO on exit

if __name__ == "__main__":
    main()

