import RPi.GPIO as GPIO
import time
import datetime

# Define the GPIO pin connected to the relay
RELAY_PIN = 17

# Define sunrise and sunset times
sunrise_time = datetime.time(7, 0, 0)
sunset_time = datetime.time(19, 0, 0)

def setup_gpio():
    """Set up the GPIO pin for the relay."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(RELAY_PIN, GPIO.OUT)
        GPIO.output(RELAY_PIN, GPIO.HIGH)  # Initialize relay to OFF (door closed)
    except RuntimeError as e:
        print(f"Error setting up GPIO: {e}")
        exit()

def control_door(open_door):
    """Open or close the chicken coop door."""
    if open_door:
        GPIO.output(RELAY_PIN, GPIO.LOW)  # Energize relay to open the door
        print("Opening chicken coop door")
    else:
        GPIO.output(RELAY_PIN, GPIO.HIGH)  # De-energize relay to close the door
        print("Closing chicken coop door")

def is_time_between(start_time, end_time):
    """Check if the current time is between the start and end times."""
    now = datetime.datetime.now().time()
    return start_time <= end_time or now >= start_time

def main():
    """Main function to control the chicken coop door."""
    setup_gpio()
    try:
        while True:
            if is_time_between(sunrise_time, sunset_time):
                control_door(True)  # Open the door
            else:
                control_door(False) # Close the door
            time.sleep(60)  # Check every minute
    except KeyboardInterrupt:
        print("Program terminated by user.")
    except RuntimeError as e:
        print(f"Runtime error: {e}")
    finally:
        GPIO.cleanup()  # Clean up GPIO on exit

if __name__ == "__main__":
    main()

