#!/usr/bin/python3
"""Provides a robust and performant driver for Adafruit DC Motor HAT."""

import atexit
import logging
import threading
import time

from Adafruit_I2C import Adafruit_I2C
from adafruit_dcmotorhat import DCMotorHATExtra

# Configure logging
logging.basicConfig(level=logging.INFO, format="%(asctime)s - %(levelname)s - %(message)s")

# Constants
MAX_PWM_FREQUENCY = 1k  # Maximum PWM frequency supported by PCA9685
DEFAULT_PWM_FREQUENCY = 60  # Default PWM frequency
MOTOR_MIN_DUTY_CYCLE = -255
MOTOR_MAX_DUTY_CYCLE = 255

class DCMotorHATError(Exception):
    """Base class for Adafruit DC Motor HAT exceptions."""
    pass

class InvalidMotorNumberError(DCMotorHATError):
    """Raised when an invalid motor number is specified."""
    pass

class MotorInitializationError(DCMotorHATError):
    """Raised when a motor fails to initialize."""
    pass

class DCMotor:
    """Represents a single DC motor connected to the Adafruit DC Motor HAT."""

    def __init__(self, motor_number, motor_hat, frequency=DEFAULT_PWM_FREQUENCY, invert=False):
        """Initializes a DCMotor instance."""
        if not 1 <= motor_number <= 4:
            raise InvalidMotorNumberError(f"Invalid motor number: {motor_number}. Must be between 1 and 4.")

        self.motor_number = motor_number
        self.motor_hat = motor_hat
        self.frequency = frequency
        self.invert = invert
        self.last_duty_cycle = 0  # Store the last set duty cycle for efficient updates
        self._setup()

    def _setup(self):
        """Sets up the motor by calling the underlying driver."""
        try:
            self.motor_hat.getMotor(self.motor_number)._speed = 0  # Ensure motor is initially stopped
            self.motor_hat.setPWMFreq(self.frequency)
            self.last_duty_cycle = self.motor_hat.getMotor(self.motor_number).getDutyCycle() #initialize last duty cycle
            logging.info(f"Motor {self.motor_number} initialized with frequency {self.frequency} Hz and invert={self.invert}")
        except Exception as e:
            logging.error(f"Failed to initialize motor {self.motor_number}: {e}")
            raise MotorInitializationError(f"Failed to initialize motor {self.motor_number}: {e}") from e

    def set_speed(self, speed):
        """Sets the motor speed.

        Args:
            speed (float): The motor speed, ranging from -1 to 1.
        """
        if not 0 <= speed <= 1:
            raise ValueError("Speed must be between 0 and 1.")

        try:
            if speed > 0:
                direction = 1 if self.invert else 0  # Regular direction
            else:
                direction = 0 if self.invert else 1  # Inverted direction

            duty_cycle = int(abs(speed) * MOTOR_MAX_DUTY_CYCLE)
            self.motor_hat.getMotor(self.motor_number).setSpeed(duty_cycle, direction)
            self.last_duty_cycle = duty_cycle
            logging.debug(f"Motor {self.motor_number} speed set to {speed}, duty cycle: {duty_cycle}")
        except Exception as e:
            logging.error(f"Failed to set speed for motor {self.motor_number}: {e}")
            raise

    def stop(self):
        """Stops the motor."""
        try:
            self.motor_hat.getMotor(self.motor_number).setSpeed(0, 0)
            self.last_duty_cycle = 0
            logging.debug(f"Motor {self.motor_number} stopped.")
        except Exception as e:
            logging.error(f"Failed to stop motor {self.motor_number}: {e}")
            raise

    def get_status(self):
        """Returns the motor status."""
        try:
            speed = self.motor_hat.getMotor(self.motor_number).getSpeed()
            duty_cycle = self.motor_hat.getMotor(self.motor_number).getDutyCycle()
            direction = 1 if self.motor_hat.getMotor(self.motor_number).getDirection() else 0
            invert = self.invert
            return {
                "motor_number": self.motor_number,
                "speed": speed,
                "duty_cycle": duty_cycle,
                "direction": direction,
                "invert": invert,
                "last_duty_cycle": self.last_duty_cycle #include last duty cycle
            }
        except Exception as e:
            logging.error(f"Failed to get status for motor {self.motor_number}: {e}")
            return None

    def close(self):
        """Stops the motor and releases resources."""
        self.stop()

    def __repr__(self):
        """Returns a string representation of the motor status."""
        return f"Motor({self.motor_number})"

class DCMotorHAT:
    """Manages a set of DC motors connected to the Adafruit DC Motor HAT."""

    def __init__(self, i2c_addr=0x40, i2c_bus_num=1, extra=DCMotorHATExtra()):
        """Initializes the DCMotorHAT."""
        try:
            self.i2c = Adafruit_I2C(i2c_addr, busnum=i2c_bus_num)
            self.hat = DCMotorHATExtra(self.i2c, extra)
            self.motors = {
                1: None,
                2: None,
                3: None,
                4: None,
            }
            for motor_number in self.motors:
                self.motors[motor_number] = None  # Initialize motors to None
        except Exception as e:
            logging.error(f"Failed to initialize DCMotorHAT: {e}")
            raise

    def __enter__(self):
        """Context management entry."""
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        """Context management exit. Ensures motors are stopped on exit."""
        try:
            for motor_number in self.motors:
                if self.motors[motor_number]:
                    self.motors[motor_number].close()
        except Exception as e:
            logging.error(f"Error during cleanup: {e}")


    def _validate_motor_number(self, motor_number):
        """Validates the motor number."""
        if not 1 <= motor_number <= 4:
            raise InvalidMotorNumberError(f"Invalid motor number: {motor_number}. Must be between 1 and 4.")

    def get_motor(self, motor_number):
        """Retrieves a motor object."""
        self._validate_motor_number(motor_number)
        if self.motors[motor_number] is None:
            try:
                self.motors[motor_number] = DCMotor(motor_number, self)
            except MotorInitializationError as e:
                logging.error(f"Failed to get motor {motor_number}: {e}")
                raise
        return self.motors[motor_number]

    def set_pwm_freq(self, pwm_freq):
        """Sets the PWM frequency for all motors.

        Args:
            pwm_freq (int): The PWM frequency in Hz.
        """
        if not MOTOR_MIN_DUTY_CYCLE <= pwm_freq <= MAX_PWM_FREQUENCY:
            logging.warning(f"PWM frequency {pwm_freq} Hz is outside the supported range ({MOTOR_MIN_DUTY_CYCLE} - {MAX_PWM_FREQUENCY} Hz).  Setting to default of {DEFAULT_PWM_FREQUENCY} Hz.")
            pwm_freq = DEFAULT_PWM_FREQUENCY

        try:
            self.hat.setPWMFreq(pwm_freq)
            logging.info(f"PWM frequency set to {pwm_freq} Hz.")
        except Exception as e:
            logging.error(f"Failed to set PWM frequency: {e}")
            raise

    def get_pwm_freq(self):
        """Returns the current PWM frequency."""
        try:
            return self.hat.getPWMFreq()
        except Exception as e:
            logging.error(f"Failed to get PWM frequency: {e}")
            return DEFAULT_PWM_FREQUENCY  # Return default frequency on error


    def close(self):
        """Releases the I2C bus."""
        try:
            self.i2c.close()
            logging.info("I2C bus closed.")
        except Exception as e:
            logging.error(f"Failed to close I2C bus: {e}")


def main():
    """Main function to demonstrate motor control."""
    try:
        hat = DCMotorHAT()
        hat.set_pwm_freq(100)  # Set PWM frequency to 100 Hz

        motor1 = hat.get_motor(1)
        motor3 = hat.get_motor(3)

        def set_speed(motor, speed):
            """Helper function to set motor speed with error handling."""
            try:
                motor.set_speed(speed)
            except ValueError as e:
                logging.error(f"Invalid speed value: {e}")
            except MotorInitializationError as e:
                logging.error(f"Failed to set speed for motor: {e}")


        # Example usage:
        set_speed(motor1, 0.5)
        time.sleep(2)
        set_speed(motor3, -0.3)
        time.sleep(2)
        set_speed(motor1, 0)
        time.sleep(1)

    except DCMotorHATError as e:
        logging.error(f"DCMotorHAT error: {e}")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        if 'hat' in locals():
            hat.close()  # Ensure motors are stopped and I2C is closed

if __name__ == "__main__":
    main()

