            self.motor_hat.getMotor(self.motor_number).setSpeed(0, 0)
            self.last_duty_cycle = 0
            logging.debug(f"Motor {self.motor_number} stopped.")
        except Exception as e:
            logging.error(f"Failed to stop motor {self.motor_number}: {e}")
            raise

    def get_status(self):
        """Returns the motor status."""
        try:
            speed = self.motor_hat.getMotor(self.motor_number).getSpeed()
            duty_cycle = self.motor_hat.getMotor(self.motor_number).getDutyCycle()
            direction = 1 if self.motor_hat.getMotor(self.motor_number).getDirection() else 0
            invert = self.invert
            return {
                "motor_number": self.motor_number,
                "speed": speed,
                "duty_cycle": duty_cycle,
                "direction": direction,
                "invert": invert,
                "last_duty_cycle": self.last_duty_cycle #include last duty cycle
            }
        except Exception as e:
            logging.error(f"Failed to get status for motor {self.motor_number}: {e}")
            return None

    def close(self):
        """Stops the motor and releases resources."""
        self.stop()

    def __repr__(self):
        """Returns a string representation of the motor status."""
        return f"Motor({self.motor_number})"

class DCMotorHAT:
    """Manages a set of DC motors connected to the Adafruit DC Motor HAT."""

    def __init__(self, i2c_addr=0x40, i2c_bus_num=1, extra=DCMotorHATExtra()):
        """Initializes the DCMotorHAT."""
        try:
            self.i2c = Adafruit_I2C(i2c_addr, busnum=i2c_bus_num)
            self.hat = DCMotorHATExtra(self.i2c, extra)
            self.motors = {
                1: None,
                2: None,
                3: None,
                4: None,
            }
            for motor_number in self.motors:
                self.motors[motor_number] = None  # Initialize motors to None
        except Exception as e:
            logging.error(f"Failed to initialize DCMotorHAT: {e}")
            raise

    def __enter__(self):
        """Context management entry."""
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        """Context management exit. Ensures motors are stopped on exit."""
        try:
            for motor_number in self.motors:
                if self.motors[motor_number]:
                    self.motors[motor_number].close()
        except Exception as e:
            logging.error(f"Error during cleanup: {e}")


    def _validate_motor_number(self, motor_number):
        """Validates the motor number."""
        if not 1 <= motor_number <= 4:
            raise InvalidMotorNumberError(f"Invalid motor number: {motor_number}. Must be between 1 and 4.")

    def get_motor(self, motor_number):
        """Retrieves a motor object."""
        self._validate_motor_number(motor_number)
        if self.motors[motor_number] is None:
            try:
                self.motors[motor_number] = DCMotor(motor_number, self)
            except MotorInitializationError as e:
                logging.error(f"Failed to get motor {motor_number}: {e}")
                raise
        return self.motors[motor_number]

    def set_pwm_freq(self, pwm_freq):
        """Sets the PWM frequency for all motors.

        Args:
