        """
        if not MOTOR_MIN_DUTY_CYCLE <= pwm_freq <= MAX_PWM_FREQUENCY:
            logging.warning(f"PWM frequency {pwm_freq} Hz is outside the supported range ({MOTOR_MIN_DUTY_CYCLE} - {MAX_PWM_FREQUENCY} Hz).  Setting to default of {DEFAULT_PWM_FREQUENCY} Hz.")
            pwm_freq = DEFAULT_PWM_FREQUENCY

        try:
            self.hat.setPWMFreq(pwm_freq)
            logging.info(f"PWM frequency set to {pwm_freq} Hz.")
        except Exception as e:
            logging.error(f"Failed to set PWM frequency: {e}")
            raise

    def get_pwm_freq(self):
        """Returns the current PWM frequency."""
        try:
            return self.hat.getPWMFreq()
        except Exception as e:
            logging.error(f"Failed to get PWM frequency: {e}")
            return DEFAULT_PWM_FREQUENCY  # Return default frequency on error


    def close(self):
        """Releases the I2C bus."""
        try:
            self.i2c.close()
            logging.info("I2C bus closed.")
        except Exception as e:
            logging.error(f"Failed to close I2C bus: {e}")


def main():
    """Main function to demonstrate motor control."""
    try:
        hat = DCMotorHAT()
        hat.set_pwm_freq(100)  # Set PWM frequency to 100 Hz

        motor1 = hat.get_motor(1)
        motor3 = hat.get_motor(3)

        def set_speed(motor, speed):
            """Helper function to set motor speed with error handling."""
            try:
                motor.set_speed(speed)
            except ValueError as e:
                logging.error(f"Invalid speed value: {e}")
            except MotorInitializationError as e:
                logging.error(f"Failed to set speed for motor: {e}")


        # Example usage:
        set_speed(motor1, 0.5)
        time.sleep(2)
        set_speed(motor3, -0.3)
        time.sleep(2)
        set_speed(motor1, 0)
        time.sleep(1)

    except DCMotorHATError as e:
        logging.error(f"DCMotorHAT error: {e}")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        if 'hat' in locals():
            hat.close()  # Ensure motors are stopped and I2C is closed

if __name__ == "__main__":
    main()

