import serial
import time
import logging
import os

# Configure logging for the servo motor controller
logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")


class ServoMotorController:
    """Encapsulates Modbus RTU reads and writes for a servo motor over UART."""

    def __init__(self, port, baudrate, timeout):
        """Initialize the servo motor controller over the given serial port."""
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.uart_connection = None

    def open_uart(self):
        """Open and configure the UART connection to the servo motor."""
        try:
            self.uart_connection = serial.Serial(
                port=self.port, baudrate=self.baudrate, timeout=self.timeout
            )
            logging.info(f"Servo motor UART opened on {self.port}")
        except serial.SerialException as e:
            logging.error(f"Failed to open UART: {e}")
            raise

    def close_uart(self):
        """Close the UART connection to the servo motor."""
        if self.uart_connection:
            self.uart_connection.close()
            logging.info("Servo motor UART closed")
        else:
            logging.warning("No UART connection to close")

    def read_holding_registers(self, start_address, count, unit_id=1):
        """Read multiple holding registers from the servo motor."""
        # Build the Modbus RTU request for holding registers
        request_bytes = (
            [unit_id, start_address >> 8, start_address & 0xff, count >> 8, count & 0xff, 0, 0, 0]
            + [0] * (32 - len(request_bytes))
        )
        try:
            self.uart_connection.write_all(request_bytes)
            response_bytes = self.uart_connection.read_all(32)
            # Verify the Modbus response length and checksum
            if len(response_bytes) != 32 or response_bytes[31] != sum(response_bytes[:31]) & 0xff:
                raise ValueError("CRC error or incomplete Modbus response")
            return response_bytes[2:6]  # Return the register values
        except serial.SerialException as e:
            logging.error(f"UART read error: {e}")
            return None

    def write_holding_registers(self, register_address, register_values, unit_id=1):
        """Write a list of register values to the servo motor."""
        # Pack the register values and address into a single list
        write_request = ([unit_id, register_address >> 8, register_address & 0xff] + register_values + [0])
        try:
            self.uart_connection.write_all(write_request)
            self.uart_connection.write_all([0] * 32)  # Acknowledge the write
            logging.info(f"Wrote register values {register_values} to address {register_address}")
        except serial.SerialException as e:
            logging.error(f"UART write error: {e}")

    def get_position(self):
        """Retrieve the current position from the servo motor."""
        return self.read_holding_registers(0, 2)


def main():
    """Main entry point for the servo motor control application."""
    servo_controller = ServoMotorController(port="/dev/serial0", baudrate=115200, timeout=0.1)
    try:
        servo_controller.open_uart()
        current_position = servo_controller.get_position()
        if current_position:
            logging.info(f"Servo position: {current_position}")
        else:
            logging.warning("Failed to read servo position")
    except serial.SerialException as e:
        logging.error(f"UART initialization failed: {e}")
    finally:
        # Ensure the UART is closed on exit
        servo_controller.close_uart()


if __name__ == "__main__":
    main()

