import time
import board
import busio
import adafruit_seesaw.seesaw
import RPi.GPIO as GPIO
import signal
import sys

# Constants
PUMP_GPIO_PIN = 17
DRY_SOIL_THRESHOLD = 500
READ_INTERVAL_SECONDS = 10
I2C_RETRY_COUNT = 3

# Global variables
i2c_bus = None
soil_sensor = None
pump_is_on = False
running = True

def initialize_i2c():
    """Initialize the I2C bus with retry logic."""
    global i2c_bus
    for attempt in range(I2C_RETRY_COUNT):
        try:
            i2c_bus = busio.I2C(board.SCL, board.SDA)
            return True
        except Exception as e:
            print(f"I2C initialization failed (attempt {attempt + 1}): {e}")
            time.sleep(1)
    print("I2C initialization failed after multiple retries.")
    return False

def initialize_soil_sensor():
    """Initialize the soil moisture sensor."""
    global soil_sensor
    try:
        soil_sensor = adafruit_seesaw.seesaw.Seesaw(i2c_bus, addr=0x48)
        return True
    except Exception as e:
        print(f"Soil sensor initialization failed: {e}")
        return False

def initialize_gpio():
    """Initialize the GPIO pin for the water pump."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(PUMP_GPIO_PIN, GPIO.OUT)
    GPIO.output(PUMP_GPIO_PIN, GPIO.LOW)  # Ensure pump is off initially

def read_soil_moisture():
    """Read the soil moisture level from the sensor."""
    try:
        moisture_level = soil_sensor.moisture_read()
        return moisture_level
    except Exception as e:
        print(f"Error reading soil moisture: {e}")
        return None

def control_water_pump(turn_on):
    """Control the water pump based on the moisture level."""
    global pump_is_on
    try:
        if turn_on and not pump_is_on:
            GPIO.output(PUMP_GPIO_PIN, GPIO.HIGH)
            pump_is_on = True
            print("Water pump turned ON")
        elif not turn_on and pump_is_on:
            GPIO.output(PUMP_GPIO_PIN, GPIO.LOW)
            pump_is_on = False
            print("Water pump turned OFF")
    except Exception as e:
        print(f"Error controlling water pump: {e}")

def cleanup_resources():
    """Clean up GPIO and I2C resources."""
    global i2c_bus, soil_sensor
    print("Cleaning up resources...")
    try:
        if i2c_bus:
            i2c_bus.deinit()
    except Exception as e:
        print(f"Error deinitializing I2C: {e}")
    try:
        if soil_sensor:
            soil_sensor.close()
    except Exception as e:
        print(f"Error closing soil sensor: {e}")
    try:
        GPIO.cleanup()
    except Exception as e:
        print(f"Error cleaning up GPIO: {e}")
    print("Resources cleaned up.")

def signal_handler(sig, frame):
    """Handle signals for graceful shutdown."""
    global running
    print("Received signal, shutting down...")
    running = False

def main_loop():
    """Main loop to read sensor data and control the water pump."""
    global running
    while running:
        moisture_level = read_soil_moisture()
        if moisture_level is not None:
            print(f"Soil moisture: {moisture_level}")
            if moisture_level < DRY_SOIL_THRESHOLD:
                control_water_pump(True)
            else:
                control_water_pump(False)
        time.sleep(READ_INTERVAL_SECONDS)

if __name__ == "__main__":
    # Set up signal handling for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not initialize_i2c():
        sys.exit(1)

    if not initialize_soil_sensor():
        sys.exit(1)

    initialize_gpio()

    try:
        main_loop()
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        cleanup_resources()
        sys.exit(0)

