import smbus
import contextlib

# Generic I2C device helper for Raspberry Pi automation
# Provides a robust and performant interface to I2C registers

class I2CDevice:
    """Manage a single I2C device on the Raspberry Pi bus."""

    def __init__(self, address, bus_number=1):
        # Open the I2C bus and store the device address
        self.address = address
        self.bus_number = bus_number
        self.bus = None

    def open(self):
        """Open the I2C bus and probe the device address."""
        try:
            self.bus = smbus.SMBus(self.bus_number)
        except OSError as bus_error:
            raise RuntimeError("Failed to open I2C bus %d: %s" % (self.bus_number, bus_error))
        try:
            self._probe_device()
        except OSError as probe_error:
            self.close()
            raise RuntimeError("I2C device at address 0x%02x not found: %s" % (self.address, probe_error))

    def _probe_device(self):
        """Check that the device at the given address acknowledges a read."""
        try:
            self.bus.read_byte(self.address)
        except IOError as probe_error:
            raise probe_error

    def close(self):
        """Close the I2C bus connection."""
        if self.bus is not None:
            self.bus.close()
            self.bus = None

    def write_byte(self, register, value):
        """Write a single byte to the specified register."""
        try:
            self.bus.write_byte_data(self.address, register, value)
        except IOError as write_error:
            raise IOError("Failed to write byte 0x%02x to register 0x%02x: %s" % (value, register, write_error))

    def read_byte(self, register):
        """Read a single byte from the specified register."""
        try:
            return self.bus.read_byte_data(self.address, register)
        except IOError as read_error:
            raise IOError("Failed to read byte from register 0x%02x: %s" % (register, read_error))

    def __enter__(self):
        """Allow the device to be used in a with statement."""
        self.open()
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        """Ensure the bus is closed when exiting the context."""
        self.close()

    def __repr__(self):
        """Return a string representation of the device."""
        return "I2CDevice(address=%02x, bus=%d)" % (self.address, self.bus_number)

