# Log file path
LOG_FILE = 'gps_coordinates_log.txt'


def initialize_serial(port, baudrate, timeout):
    """Initializes the serial connection to the GPS module."""
    try:
        return serial.Serial(port, baudrate, timeout=timeout)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None


def read_gps_data(serial_connection):
    """Reads a line of data from the GPS module via serial."""
    try:
        return serial_connection.readline().decode('ascii', errors='replace').strip()
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        return None


def parse_gps_sentence(nmea_data):
    """Parses an NMEA sentence to extract latitude, longitude, and altitude."""
    try:
        if nmea_data.startswith('$GPGGA'):
            msg = pynmea2.parse(nmea_data)
            latitude = msg.latitude
            longitude = msg.longitude
            altitude = msg.altitude
            return latitude, longitude, altitude
        return None, None, None
    except pynmea2.ParseError as e:
        print(f"Error parsing NMEA sentence: {e}")
        return None, None, None


