from threading import Thread, Lock
from time import sleep
import serial
from flask import Flask, Response, request, jsonify, abort
import os
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
UART_PORT = '/dev/ttyUSB0'
UART_BAUDRATE = 9600
UART_TIMEOUT = 1
SERVER_PORT = 5000
MAX_DATA_SIZE = 1024

# Initialize Flask app
app = Flask(__name__)

# Global variable to store data
data_store = [{"id": 1, "name": "CHIPS", "done": False}, {"id": 2, "name": "circuits", "done": False}]
data_lock = Lock()

# Serial port context manager
class SerialPort:
    """Manages the serial port connection with resource management."""

    def __init__(self, port, baudrate, timeout):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.ser = None

    def __enter__(self):
        """Opens the serial port."""
        try:
            self.ser = serial.Serial(self.port, self.baudrate, timeout=self.timeout)
            logging.info(f"Opened serial port {self.port} at {self.baudrate} baud.")
            return self.ser
        except serial.SerialException as e:
            logging.error(f"Failed to open serial port {self.port}: {e}")
            raise

    def __exit__(self, exc_type, exc_val, exc_tb):
        """Closes the serial port."""
        if self.ser and self.ser.is_open:
            self.ser.close()
            logging.info(f"Closed serial port {self.port}.")


# --- RESTful API endpoints ---

@app.route('/version', methods=['GET'])
def get_device_version():
    """Queries the connected device for its version information."""
    try:
        with SerialPort(UART_PORT, UART_BAUDRATE, UART_TIMEOUT) as ser:
            ser.write(b"*IDN?\n")
            response = ser.read(MAX_DATA_SIZE).decode('utf-8', errors='ignore')
            if ser.in_waiting > 0:
                logging.warning("Partial response received. Discarded leftover data.")
            return Response(response + "\n", mimetype='text/plain')
    except Exception as e:
        logging.error(f"Error getting device version: {e}")
        return Response("Error getting device version.\n", mimetype='text/plain', status=500)


# --- Data management ---

@app.route('/data', methods=['GET'])
def get_data():
    """Retrieves all data items."""
    with data_lock:
        return jsonify(data_store)


@app.route('/data/<int:item_id>', methods=['GET'])
def get_item(item_id):
    """Retrieves a specific data item by ID."""
    with data_lock:
        item = next((item for item in data_store if item['id'] == item_id), None)
        if item:
            return jsonify(item)
        else:
            abort(404)


@app.route('/data', methods=['POST'])
def create_item():
    """Creates a new data item."""
    try:
        item = request.get_json()
        if not all(key in item for key in ('name', 'done')):
            abort(400, "Invalid request: 'name' and 'done' fields are required.")

        new_id = data_store[-1]['id'] + 1 if data_store else 1
        item['id'] = new_id
        data_store.append(item)
        with data_lock:
            logging.info(f"Created new item: {item}")
    except Exception as e:
        logging.error(f"Error creating item: {e}")
        abort(500)

    return jsonify(item), 201


@app.route('/data/<int:item_id>', methods=['PUT'])
def update_item(item_id):
    """Updates an existing data item."""
    with data_lock:
        item = next((item for item in data_store if item['id'] == item_id), None)
        if item:
            try:
                updated_item = request.get_json()
                if not all(key in updated_item for key in ('name', 'done')):
                    abort(400, "Invalid request: 'name' and 'done' fields are required.")

                item.update(updated_item)
                logging.info(f"Updated item {item_id}: {item}")
            except Exception as e:
                logging.error(f"Error updating item {item_id}: {e}")
                abort(500)
        else:
            abort(404)

    return jsonify(item)


@app.route('/data/<int:item_id>', methods=['DELETE'])
def delete_item(item_id):
    """Deletes a data item."""
    with data_lock:
        item = next((item for item in data_store if item['id'] == item_id), None)
        if item:
            data_store.remove(item)
            logging.info(f"Deleted item {item_id}")
        else:
            abort(404)

    return jsonify({"message": f"Item {item_id} deleted."})


# --- Signal handler for graceful shutdown ---
shutdown_flag = False


def signal_handler(signum, frame):
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    global shutdown_flag
    logging.info(f"Received signal {signum}. Shutting down gracefully...")
    shutdown_flag = True


# Register signal handlers
signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)


# --- Main execution loop ---

def watch_serial_port(port, baudrate, timeout):
    """Monitors the serial port for incoming data and processes it."""
    global shutdown_flag
    try:
        with SerialPort(port, baudrate, timeout) as ser:
            logging.info(f"Monitoring serial port {port} at {baudrate} baud.")
            while not shutdown_flag:
                try:
                    line = ser.readline().decode('utf-8', errors='ignore').strip()
                    if line:
                        logging.info(f"Received: {line}")
                        # Placeholder for processing received data
                        # Example: parse_serial_data(line)
                        pass
                except serial.SerialException as e:
                    logging.error(f"Serial port error: {e}")
                    break
                except Exception as e:
                    logging.error(f"Error reading serial data: {e}")
                    break
                sleep(0.1)  # Adjust as needed
    except Exception as e:
        logging.error(f"Failed to start serial monitoring: {e}")


if __name__ == '__main__':
    # Start the serial monitoring thread
    serial_thread = Thread(target=watch_serial_port, args=(UART_PORT, UART_BAUDRATE, UART_TIMEOUT), daemon=True)
    serial_thread.start()

    try:
        # Keep the main thread alive until a signal is received
        while not shutdown_flag:
            sleep(1)
    except KeyboardInterrupt:
        logging.info("Keyboard interrupt received. Shutting down...")
    finally:
        logging.info("Shutting down Flask app...")
        app.run(host='0.0.0.0', port=SERVER_PORT, debug=False)

