import serial
import time
import datetime

# Serial port configuration for the smart energy meter
SERIAL_PORT = "/dev/serial0"
BAUD_RATE = 9600
TIMEOUT = 1

# Log file path for storing power consumption data
LOG_FILE = "power_consumption.log"


def read_power_reading(serial_connection):
    """Read a line from the serial port and return it as a string."""
    try:
        line = serial_connection.readline().decode("ascii", errors="replace").strip()
        return line
    except serial.SerialException as serial_error:
        print(f"Serial communication error: {serial_error}")
        return None


def parse_power_value(power_string):
    """Convert a power string to a floating-point power value in watts."""
    try:
        power_watts = float(power_string)
        return power_watts
    except ValueError:
        print(f"Invalid power data received: {power_string}")
        return None


def log_power_consumption(power_value, log_filepath):
    """Write the timestamp and power value to the log file."""
    timestamp_str = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    log_entry = f"{timestamp_str} – Power: {power_value} W\n"
    try:
        with open(log_filepath, "a") as log_file:
            log_file.write(log_entry)
    except IOError as io_error:
        print(f"Error writing to log file: {io_error}")


def main():
    """Main function to read power readings and log them to a file."""
    serial_connection = None
    try:
        # Open the serial port
        serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        print(f"Connected to smart energy meter on {SERIAL_PORT}")

        # Continuously read and log power consumption data
        while True:
            power_reading = read_power_reading(serial_connection)
            if power_reading:
                power_value = parse_power_value(power_reading)
                if power_value is not None:
                    log_power_consumption(power_value, LOG_FILE)

    except serial.SerialException as serial_error:
        print(f"Could not open serial port {SERIAL_PORT}: {serial_error}")
    except KeyboardInterrupt:
        print("Exiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Ensure the serial port is closed on exit
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")


if __name__ == "__main__":
    main()

